import numpy as np
import pandas as pd

# Helper functions to simulate purrr's invoke and exec
# r2py:entity:invoke
def invoke(func, x=None, *args, **kwargs):
    # R's invoke(f, list(n=10)) passes the list as the second argument .x
    # If x is a dictionary, treat it as named arguments
    if x is not None and isinstance(x, dict):
        full_kwargs = {**x, **kwargs}
        return func(*args, **full_kwargs)
    elif x is not None:
        # Treat as positional argument
        return func(x, *args, **kwargs)
    return func(*args, **kwargs)

# r2py:entity:exec
def exec_func(func, *args, **kwargs):
    return func(*args, **kwargs)

# Alias exec since 'exec' is a Python keyword
exec = exec_func

# r2py:entity:invoke_map
def invoke_map(funs, x=None, **kwargs):
    # If funs is a list of functions
    if isinstance(funs, list):
        results = []
        for f in funs:
            results.append(invoke(f, x, **kwargs))
        return results
    # If funs is a dictionary (named list in R)
    elif isinstance(funs, dict):
        return {name: invoke(f, x, **kwargs) for name, f in funs.items()}
    return None

# simulate runif
def runif(n=1, **kwargs):
    return np.random.uniform(size=n)

# simulate rnorm
def rnorm(n=1, **kwargs):
    return np.random.normal(size=n)

# simulate rcauchy
def rcauchy(n=1, **kwargs):
    return np.random.standard_cauchy(n)

# simulate paste
def paste(*args, sep=" ", **kwargs):
    # R's paste handles vectors by recycling; simplified here for the example
    return sep.join(str(x) for x in args)

# invoke(runif, list(n = 10))
invoke(runif, {'n': 10})

# invoke(runif, n = 10)
invoke(runif, n=10)

# exec(runif, n = 10)
exec(runif, n=10)

# r2py:entity:args
args = ["01a", "01b"]
# invoke(paste, args, sep = "-")
invoke(paste, args, sep="-")

# exec(paste, !!!args, sep = "-")
# In R, !!!args unpacks the list. In Python, we use *args.
exec(paste, *args, sep="-")

# r2py:entity:funs
funs = [runif, rnorm]
# funs |> invoke_map(n = 5)
invoke_map(funs, n=5)

# funs |> invoke_map(list(list(n = 10), list(n = 5)))
# R's invoke_map handles a list of argument lists by pairing them
args_list = [{'n': 10}, {'n': 5}]
[invoke(f, a) for f, a in zip(funs, args_list)]

# funs |> map(exec, n = 5)
[exec(f, n=5) for f in funs]

# funs |> map2(list(list(n = 10), list(n = 5)), function(f, args) exec(f, !!!args))
[exec(f, **a) for f, a in zip(funs, args_list)]

# r2py:entity:df
df = pd.DataFrame({
    'fun': [runif, rnorm],
    'args': [{'n': 10}, {'n': 5}]
})
# df |> pmap(function(fun, args) exec(fun, !!!args))
df.apply(lambda row: exec(row['fun'], **row['args']), axis=1).tolist()

# list(m1 = mean, m2 = median) |> invoke_map(x = rcauchy(100))
funs_stats = {"m1": np.mean, "m2": np.median}
data_cauchy = rcauchy(100)
# r2py:entity:invoke_map_2
invoke_map(funs_stats, x=data_cauchy)

# list(m1 = mean, m2 = median) |> map(function(f) f(rcauchy(100)))
# r2py:entity:map_1
{name: f(data_cauchy) for name, f in funs_stats.items()}

